```python
# ── Cell 2: the API (complete) ───────────────────────────────
import sys, threading
sys.path.insert(0, "/kaggle/input/behaviorsense-code/src")

from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel

app = FastAPI(title="BehaviorSense API")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)

STATE = {"ready": False, "error": None}

def load_models():
    """Load once, in a thread, so the tunnel URL prints immediately
    and /health reports 'loading' instead of timing out for ~3 min."""
    try:
        from behaviorsense.agents.reporter import Reporter
        from behaviorsense.agents.activity import ActivityAgent

        STATE["reporter"] = Reporter(
            "/kaggle/input/qwen2-5-7b-instruct",
            do_sample=False,        # greedy — the fix you settled on
            constrained=True,       # grammar = worst-case parseability guarantee
        )
        # Deployment settings your eval actually selected — adjust-then-smooth,
        # tau=0.25, fitted transition prior with the emergency floor re-applied.
        STATE["activity"] = ActivityAgent.from_checkpoint(
            "/kaggle/input/behaviorsense-code/checkpoints",
            logit_adjust_tau=0.25,
            smooth="viterbi_fitted",
        )
        STATE["ready"] = True
    except Exception as e:
        STATE["error"] = repr(e)

threading.Thread(target=load_models, daemon=True).start()


class DayPayload(BaseModel):
    subject_id: str
    windows: list          # raw feature windows, or precomputed logits
    date: str | None = None


@app.get("/health")
def health():
    import torch
    return {
        "ready": STATE["ready"],
        "error": STATE["error"],
        "gpu": torch.cuda.get_device_name(0) if torch.cuda.is_available() else None,
    }


@app.post("/analyze")
def analyze(payload: DayPayload):
    if not STATE["ready"]:
        raise HTTPException(503, "models still loading" if not STATE["error"] else STATE["error"])

    segments = STATE["activity"].infer_day(payload.windows)      # smoothed segments
    features = STATE["activity"].daily_features(segments)        # bouts, durations, etc.
    report   = STATE["reporter"].generate(features)              # claims JSON + prose
    verdicts = STATE["reporter"].verify(report, features)        # C1–C4, deterministic

    return {
        "subject_id": payload.subject_id,
        "date": payload.date,
        "segments": segments,
        "features": features,
        "report": report,
        "verification": verdicts,   # frontend shows faithful/flagged per claim
    }
```

The two `ActivityAgent` calls are the seam to your real code — if your entry points are named differently, only those four lines change. The contract with the frontend is just `/health` and `/analyze`.

