(() => {
  const $ = id => document.getElementById(id);
  const apiInput = $("apiUrl"), status = $("status"), runBtn = $("runBtn");
  let base = localStorage.getItem("bs_api") || "";
  let healthTimer = null;
  apiInput.value = base;
  $("day").valueAsDate = new Date();

  function setStatus(cls, text){ status.className = "pill " + cls; status.textContent = text; }

  async function checkHealth(){
    if(!base) return;
    try{
      const r = await fetch(base + "/health", {signal: AbortSignal.timeout(6000)});
      const h = await r.json();
      if(h.ready){ setStatus("ok", "connected · " + (h.gpu || "cpu")); runBtn.disabled = false; }
      else if(h.error){ setStatus("bad", "backend error — see notebook log"); runBtn.disabled = true; }
      else { setStatus("", "models loading…"); runBtn.disabled = true; }
    }catch{
      setStatus("bad", "offline — is the notebook running?"); runBtn.disabled = true;
    }
  }

  $("connectBtn").onclick = () => {
    base = apiInput.value.trim().replace(/\/+$/, "");
    if(!/^https:\/\//.test(base)){ setStatus("bad", "needs an https:// URL"); return; }
    localStorage.setItem("bs_api", base);
    setStatus("", "checking…");
    clearInterval(healthTimer);
    checkHealth();
    healthTimer = setInterval(checkHealth, 15000);
  };
  if(base) $("connectBtn").click();

  $("demoBtn").onclick = () => {
    const w = Array.from({length: 60}, (_, i) =>
      Array.from({length: 6}, (_, j) => +(Math.sin(i * .3 + j) + (Math.random() - .5) * .2).toFixed(3)));
    $("payload").value = JSON.stringify(w);
  };

  runBtn.onclick = async () => {
    let windows;
    try{ windows = JSON.parse($("payload").value); }
    catch{ alert("Window data is not valid JSON."); return; }

    runBtn.disabled = true;
    runBtn.innerHTML = '<span class="spin">◌</span> analysing…';
    try{
      const r = await fetch(base + "/analyze", {
        method: "POST",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify({subject_id: $("subj").value, date: $("day").value, windows}),
      });
      if(!r.ok) throw new Error((await r.json()).detail || r.status);
      render(await r.json());
    }catch(e){
      alert("Analysis failed: " + e.message);
    }finally{
      runBtn.disabled = false;
      runBtn.textContent = "Analyse day";
    }
  };

  function render(d){
    $("emptyState").style.display = "none";
    $("output").style.display = "block";
    $("prose").textContent = d.report?.prose || d.report?.text || "(no narrative returned)";

    const claims = d.report?.claims || [];
    const verdicts = d.verification || {};
    $("claimRows").innerHTML = claims.map((c, i) => {
      const v = Array.isArray(verdicts) ? verdicts[i] : verdicts[c.id];
      const ok = v ? v.faithful : null;
      const badge = ok === null ? "—"
        : ok ? '<span class="flag-ok">faithful</span>'
        : '<span class="flag-bad">flagged · ' + (v.failed_checks || []).join(",") + '</span>';
      return `<tr><td>${esc(c.metric || c.name || "claim")}</td>
        <td class="num">${esc(String(c.value ?? ""))} ${esc(c.direction || "")}</td>
        <td>${badge}</td></tr>`;
    }).join("") || '<tr><td colspan="3" style="color:var(--muted)">no claims emitted</td></tr>';

    $("featRows").innerHTML = Object.entries(d.features || {}).map(([k, v]) =>
      `<tr><td>${esc(k)}</td><td class="num">${esc(typeof v === "number" ? v.toFixed(2) : String(v))}</td></tr>`
    ).join("");
  }

  const esc = s => s.replace(/[&<>"']/g, m => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
})();
</script>
