```python
import itertools, json, pathlib

INPUT = pathlib.Path("/kaggle/input")
SLUGS = sorted(INPUT.glob("datasets/*/*"))
print("mounts:", [s.name for s in SLUGS])

def shape(o):
    if isinstance(o, list):
        return f"[{len(o)}]" + (shape(o[0]) if o else "empty")
    if isinstance(o, dict):
        return "{" + ",".join(sorted(o)[:6]) + "}"
    return type(o).__name__

def peek(o, depth=0, name="root"):
    pad = "   " * depth
    if isinstance(o, dict):
        print(f"{pad}{name}: dict, keys={sorted(o)[:10]}")
        for k in sorted(o)[:4]:
            peek(o[k], depth + 1, k)
    elif isinstance(o, list):
        print(f"{pad}{name}: list len={len(o)}  shape={shape(o)}")
        if o and depth < 3:
            peek(o[0], depth + 1, f"{name}[0]")
    else:
        print(f"{pad}{name}: {type(o).__name__} = {str(o)[:60]}")

for label, pat in [("v1.2", "*_pose3d.json"),
                   ("v1.1", "*_p[0-9][0-9]_r*_c[0-9][0-9].json"),
                   ("untrimmed", "results_P*T*C*_lcrnet*.json")]:
    hits = [h for s in SLUGS
            for h in itertools.islice(itertools.chain(s.glob(pat), s.glob(f"*/{pat}")), 1)]
    print(f"\n===== {label}: {len(hits)} found")
    for p in hits:
        print(p.name, f"({p.stat().st_size / 1e3:.0f} KB)")
        peek(json.loads(p.read_text()))
